# Bearer-token authentication for the MCP endpoint (generated by maquina:mcp).
# The token comes from maquina:oauth and must have been issued for this
# server's /mcp resource (RFC 8707); a token for another resource, a revoked
# or expired one, or one whose user is blocked all get the same 401.
#
# It sets @access_token and @mcp_user. It never touches Current: a token is
# not a cookie session, so Current.user stays nil under it.
module McpAuthenticatable
  extend ActiveSupport::Concern

  # last_used_at feeds the Connected apps page; once a minute is precise
  # enough and spares a write on every call.
  LAST_USED_PRECISION = 1.minute

  private

  def authenticate_mcp_token
    token = AccessToken.authenticate(bearer_token)
    unless token && token.resource == mcp_resource
      Rails.logger.info("[MCP] bearer token refused from #{request.remote_ip}")
      return false
    end

    @access_token = token
    @mcp_user = token.user
    touch_last_used(token)
    true
  end

  # The raw token, read once and never logged.
  def bearer_token
    request.authorization.to_s[/\ABearer +(\S+)\z/i, 1]
  end

  def touch_last_used(token)
    return if token.last_used_at&.after?(LAST_USED_PRECISION.ago)

    token.update_column(:last_used_at, Time.current)
  end

  # The 401 and 403 challenge. It names the protected-resource metadata so a
  # client can find the authorization server, and the scope to ask for.
  def mcp_challenge(error: nil, scope: "read")
    metadata = %(resource_metadata="#{request.base_url}/.well-known/oauth-protected-resource/mcp")

    if error
      %(Bearer error="#{error}", scope="#{scope}", #{metadata})
    else
      %(Bearer #{metadata}, scope="#{scope}")
    end
  end

  def mcp_resource
    "#{request.base_url}/mcp"
  end

  # The token's digest, so the limit follows the client and not a shared
  # egress address. The raw token never becomes a cache key.
  def mcp_rate_limit_key
    token = bearer_token
    token ? "token:#{AccessToken.digest(token)}" : "ip:#{request.remote_ip}"
  end
end
